alter table cali_workspace.profiles add column if not exists signature_mode text not null default 'generated', add column if not exists signature_url text;
alter table cali_workspace.profiles drop constraint if exists profiles_signature_mode_check;
alter table cali_workspace.profiles add constraint profiles_signature_mode_check check (signature_mode in ('generated','uploaded'));
alter table cali_workspace.reports add column if not exists approval_identity_snapshot jsonb, add column if not exists acknowledgement_identity_snapshot jsonb, add column if not exists acknowledged_at timestamptz, add column if not exists acknowledged_by uuid, add column if not exists acknowledgement_protocol text, add column if not exists client_first_opened_at timestamptz, add column if not exists client_last_opened_at timestamptz, add column if not exists client_open_count integer not null default 0, add column if not exists client_pdf_count integer not null default 0;
create table if not exists cali_workspace.report_client_events(id uuid primary key default gen_random_uuid(),report_id uuid not null references cali_workspace.reports(id) on delete cascade,company_id uuid not null references cali_workspace.companies(id) on delete cascade,user_id uuid not null references cali_workspace.profiles(id) on delete cascade,event_type text not null check(event_type in('opened','pdf_opened','acknowledged','drive_saved')),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists report_client_events_report_created_idx on cali_workspace.report_client_events(report_id,created_at desc);create index if not exists report_client_events_user_created_idx on cali_workspace.report_client_events(user_id,created_at desc);alter table cali_workspace.report_client_events enable row level security;drop policy if exists report_client_events_admin_select on cali_workspace.report_client_events;create policy report_client_events_admin_select on cali_workspace.report_client_events for select to authenticated using(exists(select 1 from cali_workspace.profiles p where p.id=auth.uid() and p.role='admin' and p.active=true));grant select on cali_workspace.report_client_events to authenticated;
create or replace function cali_workspace.update_my_profile_v55(p_full_name text,p_job_title text default null,p_phone text default null,p_avatar_url text default null,p_whatsapp text default null,p_linkedin_url text default null,p_instagram_url text default null,p_avatar_position_x numeric default 50,p_avatar_position_y numeric default 50,p_avatar_zoom numeric default 1,p_signature_mode text default 'generated',p_signature_url text default null) returns cali_workspace.profiles language plpgsql security definer set search_path to 'cali_workspace','public' as $$ declare updated_profile cali_workspace.profiles;begin update cali_workspace.profiles set full_name=nullif(trim(p_full_name),''),job_title=nullif(trim(coalesce(p_job_title,'')),''),phone=nullif(trim(coalesce(p_phone,'')),''),avatar_url=nullif(trim(coalesce(p_avatar_url,'')),''),whatsapp=nullif(trim(coalesce(p_whatsapp,'')),''),linkedin_url=nullif(trim(coalesce(p_linkedin_url,'')),''),instagram_url=nullif(trim(coalesce(p_instagram_url,'')),''),avatar_position_x=greatest(0,least(100,coalesce(p_avatar_position_x,50))),avatar_position_y=greatest(0,least(100,coalesce(p_avatar_position_y,50))),avatar_zoom=greatest(1,least(3,coalesce(p_avatar_zoom,1))),signature_mode=case when p_signature_mode='uploaded' then 'uploaded' else 'generated' end,signature_url=nullif(trim(coalesce(p_signature_url,'')),''),updated_at=now() where id=auth.uid() returning * into updated_profile;if updated_profile.id is null then raise exception 'profile_not_found';end if;return updated_profile;end;$$;grant execute on function cali_workspace.update_my_profile_v55(text,text,text,text,text,text,text,numeric,numeric,numeric,text,text) to authenticated;
create or replace function cali_workspace.capture_report_approval_identity_v55() returns trigger language plpgsql security definer set search_path to 'cali_workspace','public' as $$ declare p cali_workspace.profiles;begin if new.status='approved' and old.status is distinct from 'approved' and new.approval_identity_snapshot is null then select * into p from cali_workspace.profiles where id=auth.uid();if p.id is not null then new.approval_identity_snapshot=jsonb_build_object('user_id',p.id,'full_name',p.full_name,'job_title',p.job_title,'avatar_url',p.avatar_url,'avatar_position_x',p.avatar_position_x,'avatar_position_y',p.avatar_position_y,'avatar_zoom',p.avatar_zoom,'signature_mode',coalesce(p.signature_mode,'generated'),'signature_url',p.signature_url,'signed_at',coalesce(new.approved_at,now()));end if;end if;return new;end;$$;drop trigger if exists reports_capture_approval_identity_v55 on cali_workspace.reports;create trigger reports_capture_approval_identity_v55 before update of status on cali_workspace.reports for each row execute function cali_workspace.capture_report_approval_identity_v55();
create or replace function cali_workspace.record_report_client_event_v55(p_report_id uuid,p_event_type text) returns jsonb language plpgsql security definer set search_path to 'cali_workspace','public' as $$ declare p cali_workspace.profiles;r cali_workspace.reports;recent boolean;now_ts timestamptz:=now();begin select * into p from cali_workspace.profiles where id=auth.uid() and role='client' and active=true;if p.id is null then raise exception 'client_profile_required';end if;select * into r from cali_workspace.reports where id=p_report_id and company_id=p.company_id and status in('sent','published');if r.id is null then raise exception 'report_not_available';end if;if p_event_type not in('opened','pdf_opened','drive_saved') then raise exception 'invalid_event_type';end if;select exists(select 1 from cali_workspace.report_client_events e where e.report_id=r.id and e.user_id=p.id and e.event_type=p_event_type and e.created_at>now_ts-interval '10 seconds') into recent;if not recent then insert into cali_workspace.report_client_events(report_id,company_id,user_id,event_type) values(r.id,r.company_id,p.id,p_event_type);if p_event_type='opened' then update cali_workspace.reports set client_first_opened_at=coalesce(client_first_opened_at,now_ts),client_last_opened_at=now_ts,client_open_count=coalesce(client_open_count,0)+1 where id=r.id;elsif p_event_type='pdf_opened' then update cali_workspace.reports set client_pdf_count=coalesce(client_pdf_count,0)+1 where id=r.id;end if;end if;select * into r from cali_workspace.reports where id=p_report_id;return jsonb_build_object('open_count',r.client_open_count,'pdf_count',r.client_pdf_count,'first_opened_at',r.client_first_opened_at,'last_opened_at',r.client_last_opened_at,'acknowledged_at',r.acknowledged_at,'acknowledgement_protocol',r.acknowledgement_protocol);end;$$;grant execute on function cali_workspace.record_report_client_event_v55(uuid,text) to authenticated;
create or replace function cali_workspace.acknowledge_report_v55(p_report_id uuid) returns jsonb language plpgsql security definer set search_path to 'cali_workspace','public' as $$ declare p cali_workspace.profiles;r cali_workspace.reports;protocol text;snap jsonb;now_ts timestamptz:=now();begin select * into p from cali_workspace.profiles where id=auth.uid() and role='client' and active=true;if p.id is null then raise exception 'client_profile_required';end if;select * into r from cali_workspace.reports where id=p_report_id and company_id=p.company_id and status in('sent','published') for update;if r.id is null then raise exception 'report_not_available';end if;if r.acknowledged_at is not null then return jsonb_build_object('acknowledged_at',r.acknowledged_at,'acknowledgement_protocol',r.acknowledgement_protocol,'identity',r.acknowledgement_identity_snapshot);end if;protocol:='CALI-CIE-'||to_char(now_ts at time zone 'America/Sao_Paulo','YYYYMMDD')||'-'||upper(substr(md5(random()::text||clock_timestamp()::text||p.id::text),1,6));snap:=jsonb_build_object('user_id',p.id,'full_name',p.full_name,'job_title',p.job_title,'avatar_url',p.avatar_url,'avatar_position_x',p.avatar_position_x,'avatar_position_y',p.avatar_position_y,'avatar_zoom',p.avatar_zoom,'signature_mode',coalesce(p.signature_mode,'generated'),'signature_url',p.signature_url,'signed_at',now_ts,'protocol',protocol);update cali_workspace.reports set acknowledged_at=now_ts,acknowledged_by=p.id,acknowledgement_protocol=protocol,acknowledgement_identity_snapshot=snap where id=r.id;insert into cali_workspace.report_client_events(report_id,company_id,user_id,event_type,metadata) values(r.id,r.company_id,p.id,'acknowledged',jsonb_build_object('protocol',protocol));insert into cali_workspace.activity_log(company_id,actor_user_id,event_type,entity_type,entity_id,metadata) values(r.company_id,p.id,'report_acknowledged','report',r.id,jsonb_build_object('protocol',protocol));return jsonb_build_object('acknowledged_at',now_ts,'acknowledgement_protocol',protocol,'identity',snap);end;$$;grant execute on function cali_workspace.acknowledge_report_v55(uuid) to authenticated;
update cali_workspace.reports r set approval_identity_snapshot=jsonb_build_object('user_id',p.id,'full_name',p.full_name,'job_title',p.job_title,'avatar_url',p.avatar_url,'avatar_position_x',p.avatar_position_x,'avatar_position_y',p.avatar_position_y,'avatar_zoom',p.avatar_zoom,'signature_mode',coalesce(p.signature_mode,'generated'),'signature_url',p.signature_url,'signed_at',coalesce(r.approved_at,r.sent_at,r.published_at,r.updated_at)) from cali_workspace.profiles p where r.approval_identity_snapshot is null and r.status in('approved','sent','published') and p.id=coalesce(r.approved_by,(select p2.id from cali_workspace.profiles p2 where p2.role='admin' and p2.active=true order by p2.created_at asc limit 1));